<script setup lang="ts">
import { computed, ref } from 'vue'
import AppHeader from '@/components/AppHeader.vue'
import AppTabbar from '@/components/AppTabbar.vue'
import SectionTitle from '@/components/SectionTitle.vue'
import AiFab from '@/components/AiFab.vue'
import QuickRecordSheet from '@/components/QuickRecordSheet.vue'
import { feedingPlan, quickActions } from '@/data/mock'
import { usePetStore } from '@/stores/pet'
const store = usePetStore()
const sheet = ref(false)
const activeType = ref('feeding')
const upcoming = computed(() => feedingPlan.find((item) => !item.done) || feedingPlan[0])
const reminder = computed(() => store.activeReminders[0])
function openQuick(type: string) { activeType.value = type; sheet.value = true }
function openAi() { uni.navigateTo({ url: '/pages/ai/index' }) }
function openGrowth() { uni.navigateTo({ url: '/pages/growth/index' }) }
function openReminders() { uni.navigateTo({ url: '/pages/reminder/index' }) }
function openPet() { uni.navigateTo({ url: '/pages/pet/detail' }) }
function finishReminder() { if (!reminder.value) return; store.completeReminder(reminder.value.id); uni.showToast({ title: '提醒已完成', icon: 'success' }) }
</script>
<template>
  <view class="screen"><AppHeader title="早上好" subtitle="8 月 18 日，星期一" action="notification" @action="openReminders" />
    <view class="body">
      <view class="pet-summary" @tap="openPet"><image :src="store.pet.avatar" mode="aspectFill" /><view><text>{{ store.pet.name }}</text><text>{{ store.pet.breed }} · {{ store.pet.age }}</text></view><view class="healthy"><view /><text>一切正常</text></view><uni-icons type="arrow-right" size="16" color="#C7C7CC" /></view>
      <SectionTitle title="今天" />
      <view class="today-card"><view class="today-top"><view><text class="caption">接下来</text><text class="next-time">{{ upcoming.time }}</text></view><view class="next"><text>{{ upcoming.title }}</text><text>{{ upcoming.detail }}</text></view></view><view class="progress"><view><text>今日喂养计划</text><text>2 / 3 已完成</text></view><view class="track"><view /></view></view></view>
      <SectionTitle title="今日安排" />
      <view class="group"><view v-for="item in feedingPlan" :key="item.time" class="plan-row"><view class="check" :class="{ done: item.done }"><uni-icons v-if="item.done" type="checkmarkempty" size="15" color="#FFFFFF" /></view><text class="time">{{ item.time }}</text><view><text>{{ item.title }}</text><text>{{ item.detail }}</text></view></view></view>
      <SectionTitle title="提醒" more="查看全部" @more="openReminders" />
      <view v-if="reminder" class="group"><view class="reminder-row"><view class="reminder-icon" :class="reminder.tint"><uni-icons :type="reminder.icon" size="18" :color="reminder.tint === 'orange' ? '#FF9500' : reminder.tint === 'green' ? '#34C759' : '#007AFF'" /></view><view><text>{{ reminder.title }}</text><text>{{ reminder.date }} · {{ reminder.repeat }}</text></view><button @tap="finishReminder">完成</button></view></view>
      <SectionTitle title="快速记录" />
      <view class="action-grid"><view v-for="(item, index) in quickActions" :key="item.type" class="action" :class="{ right: index % 3 !== 2, bottom: index < 3 }" @tap="openQuick(item.type)"><view class="action-icon" :class="item.tint"><uni-icons :type="item.icon" size="21" :color="item.tint === 'orange' ? '#FF9500' : item.tint === 'green' ? '#34C759' : '#007AFF'" /></view><text>{{ item.label }}</text></view></view>
      <SectionTitle title="为你发现" />
      <view class="insight" @tap="openAi"><view class="insight-icon"><uni-icons type="chat-filled" size="19" color="#007AFF" /></view><view><text>豆包最近状态很稳定</text><text>过去 14 天体重没有明显波动。</text></view><uni-icons type="arrow-right" size="16" color="#8E8E93" /></view>
      <SectionTitle title="去年今日" @more="openGrowth" />
      <view class="memory" @tap="openGrowth"><image :src="store.pet.avatar" mode="aspectFill" /><view><text>又是一起晒太阳的一天</text><text>2025 年 8 月 18 日</text></view></view>
      <view class="spacer" />
    </view><AiFab @tap="openAi" /><AppTabbar active="home" /><QuickRecordSheet v-model="sheet" :type="activeType" />
  </view>
</template>
