-size: 22rpx; }.insight { display: flex; align-items: center; padding: 22rpx; border-radius: 28rpx; background: #FFFFFF; }.insight-icon { display: flex; width: 58rpx; height: 58rpx; align-items: center; justify-content: center; border-radius: 18rpx; background: $blue-soft; }.insight > view:nth-child(2) { display: flex; flex: 1; flex-direction: column; gap: 6rpx; margin-left: 16rpx; }.insight > view:nth-child(2) text:first-child { font-size: 27rpx; font-weight: 600; }.insight > view:nth-child(2) text:last-child { color: $tertiary; font-size: 21rpx; }.memory { display: flex; align-items: center; padding: 18rpx; border-radius: 28rpx; background: $surface; }.memory image { width: 114rpx; height: 114rpx; border-radius: 20rpx; }.memory view { display: flex; flex: 1; flex-direction: column; gap: 9rpx; margin-left: 18rpx; }.memory text:first-child { font-size: 27rpx; font-weight: 600; }.memory text:last-child { color: $tertiary; font-size: 21rpx; }.spacer { height: 160rpx; }
